export const AGENT05_MODULE_VERSION = '1.0.0';
export const AGENT05_MODULE_ID = 'agent05_conditional_events';

export type Agent05ChainPhase = 'signal' | 'pressure' | 'rupture' | 'recovery';
export type Agent05ResponseKind = 'crisis_choice' | 'dilemma_choice' | 'defer' | 'escalate';

export interface Agent05ChainDescriptor {
  chainId: string;
  region: string;
  theme: ContentTheme;
  phases: Agent05ChainPhase[];
  crisisTemplateId: string;
  dilemmaTemplateId: string;
  worldEventTemplateId: string;
  entryFlag: string;
  exitFlag: string;
  simulationKeys: string[];
}

export interface Agent05PendingPlayerResponse {
  id: string;
  chainId: string;
  templateId: string;
  regionId: string;
  kind: Agent05ResponseKind;
  choiceIds: string[];
  openedDay: number;
  expiresDay: number;
  simulationSnapshot: { day: number; stability: number | null; money: number; activeCrises: number };
}

export interface Agent05SimulationEventState {
  version: 1;
  activeChains: Record<string, { phase: Agent05ChainPhase; startedDay: number; lastTickDay: number }>;
  pendingResponses: Agent05PendingPlayerResponse[];
  resolvedChainIds: string[];
  telemetry: { eligibilityChecks: number; responsesOpened: number; responsesResolved: number };
}

export function createDefaultAgent05SimulationEventState(): Agent05SimulationEventState {
  return { version: 1, activeChains: {}, pendingResponses: [], resolvedChainIds: [], telemetry: { eligibilityChecks: 0, responsesOpened: 0, responsesResolved: 0 } };
}

export function sanitizeAgent05SimulationEventState(raw: unknown): Agent05SimulationEventState {
  const base = createDefaultAgent05SimulationEventState();
  if (!raw || typeof raw !== 'object') return base;
  const r: any = raw;
  if (r.activeChains && typeof r.activeChains === 'object') {
    Object.entries(r.activeChains).forEach(([k, v]: any) => {
      if (v && typeof v === 'object' && typeof v.startedDay === 'number') {
        base.activeChains[String(k)] = { phase: (['signal', 'pressure', 'rupture', 'recovery'].includes(v.phase) ? v.phase : 'signal') as Agent05ChainPhase, startedDay: Number(v.startedDay) || 1, lastTickDay: Number(v.lastTickDay) || Number(v.startedDay) || 1 };
      }
    });
  }
  base.pendingResponses = (Array.isArray(r.pendingResponses) ? r.pendingResponses : []).filter((p: any) => p && typeof p.id === 'string').slice(0, 8);
  base.resolvedChainIds = (Array.isArray(r.resolvedChainIds) ? r.resolvedChainIds : []).map(String).slice(-40);
  if (r.telemetry && typeof r.telemetry === 'object') {
    base.telemetry.eligibilityChecks = Math.max(0, Number(r.telemetry.eligibilityChecks) || 0);
    base.telemetry.responsesOpened = Math.max(0, Number(r.telemetry.responsesOpened) || 0);
    base.telemetry.responsesResolved = Math.max(0, Number(r.telemetry.responsesResolved) || 0);
  }
  return base;
}

function a05ChainId(region: string, theme: string, idx: number): string {
  return `a05_${region.toLowerCase()}_${theme}_${idx}`;
}

function a05PhaseTitle(phase: Agent05ChainPhase, region: string, theme: string): string {
  const labels: Record<Agent05ChainPhase, string> = { signal: 'Early warning', pressure: 'System pressure', rupture: 'Rupture event', recovery: 'Recovery window' };
  return `${labels[phase]} — ${region} ${theme}`;
}

