export const AGENT05_CHAIN_BY_ID: Record<string, Agent05ChainDescriptor> = Object.fromEntries(AGENT05_CHAIN_DESCRIPTORS.map(d => [d.chainId, d]));

const a05Crtpl = (o: Omit<CrisisContentTemplate, 'kind'>): CrisisContentTemplate => ({ kind: 'crisis', ...o });

function a05BuildCrisisChain(desc: Agent05ChainDescriptor): CrisisChain {
  const catMap: Record<string, CrisisCategory> = { mining: 'economic', agriculture: 'environmental', energy: 'infrastructure', renewables: 'infrastructure', technology: 'technological', research: 'technological', trade: 'infrastructure', logistics: 'infrastructure', finance: 'economic', tourism: 'economic', water: 'environmental', manufacturing: 'economic', governance: 'technological', environment: 'environmental', exploration: 'economic' };
  const category = catMap[desc.theme] || 'economic';
  return v93Chain(desc.chainId.replace(/^a05_/, ''), desc.crisisTemplateId.replace(/_crisis$/, '').replace(/^a05_/, ''), `Simulation-gated ${desc.theme} stress in ${desc.region}.`, category, [desc.region], {
    signal: { title: a05PhaseTitle('signal', desc.region, desc.theme), description: 'Indicators cross thresholds tied to live regional simulation.', turns: 2, effects: [], choices: [{ id: 'prepare', label: 'Fund early mitigation', description: 'Spend before the rupture phase', cost: 1200, actions: 1, stability: 5, p: 0.78 }, { id: 'wait', label: 'Monitor and defer', description: 'Accept higher rupture risk', cost: 0, actions: 0, stability: 0, p: 0.32 }], onFailure: 'pressure' },
    pressure: { title: a05PhaseTitle('pressure', desc.region, desc.theme), description: 'Secondary systems load; prices and stability drift.', turns: 2, effects: [['investmentYield', 0.97]], choices: [{ id: 'stabilize', label: 'Stabilize exposed assets', description: 'Cap losses before rupture', cost: 1800, actions: 1, stability: 6, p: 0.75 }], onSuccess: 'recovery', onFailure: 'rupture' },
    rupture: { title: a05PhaseTitle('rupture', desc.region, desc.theme), description: 'The conditional chain fires its main shock.', turns: 3, effects: [['travelCost', 1.2]], choices: [{ id: 'respond', label: 'Execute response playbook', description: 'Canonical crisis choice path', cost: 2200, actions: 1, stability: 8, p: 0.82 }], onSuccess: 'recovery', onFailure: 'recovery' },
    recovery: { title: a05PhaseTitle('recovery', desc.region, desc.theme), description: 'Recovery contracts and standing opportunities open.', turns: 3, effects: [], choices: [{ id: 'rebuild', label: 'Fund recovery program', description: 'Sets exit flag for chain memory', cost: 1500, actions: 1, stability: 5, p: 0.9 }] }
  }, ['signal', 'pressure', 'rupture', 'recovery']);
}

