export const AGENT05_CRISIS_CONTENT_REGISTRY_V2: CrisisContentTemplate[] = AGENT05_CHAIN_DESCRIPTORS.map(desc => {
  const reqs = AGENT05_CRISIS_REQUIRES[desc.crisisTemplateId] || [{ k: 'no_crisis_here' }, { k: 'day_min', day: 5 }];
  const catMap: Record<string, CrisisCategory> = { mining: 'economic', agriculture: 'environmental', energy: 'infrastructure', renewables: 'infrastructure', technology: 'technological', research: 'technological', trade: 'infrastructure', logistics: 'infrastructure', finance: 'economic', tourism: 'economic', water: 'environmental', manufacturing: 'economic', governance: 'technological', environment: 'environmental', exploration: 'economic' };
  const cat = catMap[desc.theme] || 'economic';
  return a05Crtpl({
    id: desc.crisisTemplateId,
    title: `${desc.region} ${desc.theme} conditional chain`,
    summary: `Simulation-gated crisis chain for ${desc.theme} stress in ${desc.region}.`,
    category: cat as CrisisCategory,
    regions: [desc.region],
    themes: [desc.theme],
    roles: ['crisis', 'stability'],
    rarity: idxMod(desc.chainId) === 0 ? 'rare' : 'uncommon',
    cooldownDays: 18 + (idxMod(desc.chainId) % 10),
    requires: reqs,
    chain: a05BuildCrisisChain(desc)
  });
});
function idxMod(chainId: string): number { let h = 0; for (let i = 0; i < chainId.length; i++) h = (h * 31 + chainId.charCodeAt(i)) >>> 0; return h % 17; }

